65	<script>
66	import router from '@system.router'
67	import { storageService } from '../../common/services/storage'
68	import { POSTURE_STATUS, POSTURE_LABELS_ZH, POSTURE_COLORS } from '../../config/constants'
69	
70	export default {
71	  private: {
72	    postureStatus: POSTURE_STATUS.UNKNOWN,
73	    postureLabel: '未知',
74	    postureColor: '#9E9E9E',
75	    postureEmoji: '❓',
76	    todayScore: 0,
77	    goodCount: 0,
78	    fairCount: 0,
79	    poorCount: 0
80	  },
81	
82	  async onReady() {
83	    await this.loadData()
84	  },
85	
86	  async onShow() {
87	    await this.loadData()
88	  },
89	
90	  async loadData() {
91	    try {
92	      // 加载今日数据
93	      const today = new Date().toISOString().split('T')[0]
94	      const dailyData = await storageService.getDailyData(today)
95	
96	      this.goodCount = dailyData.summary.good
97	      this.fairCount = dailyData.summary.fair
98	      this.poorCount = dailyData.summary.poor
99	      this.todayScore = dailyData.score
100	
101	      // 判断当前状态
102	      if (dailyData.summary.total > 0) {
103	        const goodRatio = dailyData.summary.good / dailyData.summary.total
104	        if (goodRatio >= 0.7) {
105	          this.postureStatus = POSTURE_STATUS.GOOD
106	        } else if (goodRatio >= 0.4) {
107	          this.postureStatus = POSTURE_STATUS.FAIR
108	        } else {
109	          this.postureStatus = POSTURE_STATUS.POOR
110	        }
111	      }
112	
113	      this.postureLabel = POSTURE_LABELS_ZH[this.postureStatus]
114	      this.postureColor = POSTURE_COLORS[this.postureStatus]
115	      this.postureEmoji = this.getEmoji(this.postureStatus)
116	    } catch (e) {
117	      console.error('[Index] Load data failed:', e)
118	    }
119	  },
120	
121	  getEmoji(status) {
122	    const emojis = {
123	      [POSTURE_STATUS.GOOD]: '😊',
124	      [POSTURE_STATUS.FAIR]: '😐',
125	      [POSTURE_STATUS.POOR]: '😟',
126	      [POSTURE_STATUS.UNKNOWN]: '❓'
127	    }
128	    return emojis[status] || '❓'
129	  },
